        "codeNote": "import test пен expect қосады. test сценарийді атайды; async, await әрекетті күтеді. const мәнге атау береді. page браузерді басқарады; request API сұранысын жібереді; expect факт пен күтуді салыстырады. Кодты тұтас қой. Бір ретте 1–3 тест; цикл, өз функцияң, кез келген JavaScript қолдаусыз."
